head.script:
    	
    	    	
            /*******************headerInit******************************************************
             * function    : headerInit
             * Description : header Init
             * Parameter   : null
             * Return      : null
             **************************************************************************/
             function headerInit() { 
	             makeTopMenu();
	             attachMenuEvent();
             }
    	
            /**************************************************************************
             * function    : makeTopMenu
             * Description : 상단 메뉴를 생성한다.
             * Parameter   : null
             * Return      : null
             **************************************************************************/  
             function makeTopMenu() {
				debugger;
               	var topMenuCount = 9;
             	var parentMenuList = WebSquare.ModelUtil.findInstanceNodes("respMenu/root/message/BISComMenuListDTO/BISComMenuDTO[depth='1']");
                for (var i=0 ; i<=topMenuCount ; i++) {
                	genLv1.insert();
                	
                	var parenLebel = WebSquare.xml.getValue( parentMenuList[i], "divisionNm" );
                	var parentDivisionId = WebSquare.xml.getValue( parentMenuList[i], "divisionId" );
                	
                	var imgObj = genLv1.getChild( i , "imgLv1" );
                	var objSeq = (i < 9) ? "0"+(i+1) : i+1;
                	imgObj.setAlt(parenLebel);
                	imgObj.setSrc("/images/menu/menu"+(objSeq)+"_off.png");
                	
                	var subGen = genLv1.getChild( i , "genLv2" );
                	subGen.addClass("sub"+objSeq);
                	
                	var objGrpLv1A = genLv1.getChild(i, "grpLv1A");
                	objGrpLv1A.setUserData( "divisionId" , parentDivisionId );
                	objGrpLv1A.setUserData( "menuIndex" , i );
                	
                	var subMenuList = WebSquare.ModelUtil.findInstanceNodes("respMenu/root/message/BISComMenuListDTO/BISComMenuDTO[parentDivId='"+parentDivisionId+"']");
                	for (var j=0 ; j<subMenuList.length ; j++) {
                		subGen.insert();
                		var subLabel = WebSquare.xml.getValue( subMenuList[j], "divisionNm" );
                		var subDivisionId = WebSquare.xml.getValue( subMenuList[j], "divisionId" );
                		
                		if(j == 0) {
                			var firstObj = subGen.getChild( j , "grpLv2Li" );
                			firstObj.addClass("top");
                		}

                		var txtObj = subGen.getChild( j , "txtLv2" );
                		txtObj.setLabel(subLabel);
                		if(subLabel.length > 10) txtObj.setStyle("letter-spacing","-0.5pt");
                		
                		
	                	var objGrpLv2A = subGen.getChild(j, "grpLv2A");
	                	objGrpLv2A.setUserData( "divisionId" , subDivisionId );
	                	objGrpLv2A.setUserData( "parentDivisionId" , parentDivisionId );
	                	objGrpLv2A.setUserData( "parentMenuIndex" , i );
	                	objGrpLv2A.setUserData( "menuIndex" , j );
                	}
                }
             }
             
            /**************************************************************************
             * function    : attachMenuEvent
             * Description : 상단 메뉴에 이벤트를 설정한다.
             * Parameter   : null
             * Return      : null
             **************************************************************************/  
             function attachMenuEvent() {
				  var menuF = $('#gnb-wrap > #gnb > ul > li ');
				  var menuU = $('#gnb-wrap > #gnb > ul > li > ul');
				  var menuS = $('#gnb-wrap > #gnb > ul > li > ul > li');
				  $(menuF).hover(function(){$(this).addClass('on');},function(){$(this).removeClass('on');});
				  $(menuU).hover(function(){$(this).parent().addClass('on');},function(){$(this).parent().removeClass('on');});
				  $(menuS).hover(function(){$(this).addClass('on');},function(){$(this).removeClass('on');});
				  $(menuS).click(function(){$(this).addClass('lock').siblings().removeClass('lock');});
				  $(menuF).focusin(function(){$(this).addClass('on');});
				  $(menuF).focusout(function(){$(this).removeClass('on');});
				  $(menuS).focusin(function(){$(this).addClass('on');});
				  $(menuS).focusout(function(){$(this).removeClass('on');});
				  $('#gnb').bind('mouseenter focusin', function(){
				  /*
				    $('#gnb-wrap').stop().animate({'height':'286px'},200);
				    $('#gnb ul ul').stop().animate({'height':'249px'},200);
				  */
				    $('#gnb-wrap').stop().animate({'height':'364px'},200);
				    $('#gnb ul ul').stop().animate({'height':'327px'},200);
				  });
				  $('#gnb').bind('mouseleave focusout', function(){
				    $('#gnb-wrap').stop().animate({'height':'34px'},200);
				    $('#gnb ul ul').stop().animate({'height':'0'},200);
				  });
             }             
             
             
            /**************************************************************************
             * function    : clickMenu
             * Description : 상단 메뉴 클릭시 필요한 처리를 한다.
             * Parameter   : null
             * Return      : null
             **************************************************************************/  
             function clickMenu(obj) {
	             var divisionId = obj.getUserData("divisionId");
             	 var parentDivisionId = (obj.getUserData("parentDivisionId")==null) ? "" : obj.getUserData("parentDivisionId");
             	 var parentMenuIndex = (obj.getUserData("parentMenuIndex")==null) ? "" : obj.getUserData("parentMenuIndex");
             	 var menuIndex = (obj.getUserData("menuIndex")==null) ? "" : obj.getUserData("menuIndex");
	           	 var secondDeptMenu = WebSquare.ModelUtil.findInstanceNodes("respMenu/root/message/BISComMenuListDTO/BISComMenuDTO[divisionId='"+divisionId+"']");
				 var runFilePageNm = WebSquare.xml.getValue( secondDeptMenu[0], "runFilepageNm" );
				 				 
				 if(runFilePageNm.indexOf("href:")>-1){
					var menuUrl = runFilePageNm.slice(runFilePageNm.indexOf(":")+1,runFilePageNm.length);
					window.open(menuUrl);
					return;
				 }
				 if(isMain){
	           	 	var url = sub_url+"&divisionId="+divisionId+"&parentDivisionId="+parentDivisionId+"&parentMenuIndex="+parentMenuIndex+"&menuIndex="+menuIndex;
	           	 	window.location.href= url;
	           	 } else {
           	 	 	makeLeftMenu(divisionId, parentDivisionId, parentMenuIndex, menuIndex);
	           	 }
             }

            /**************************************************************************
             * function    : closeTopMenu
             * Description : 상단 메뉴를 닫는다.
             * Parameter   : null
             * Return      : null
             **************************************************************************/  
             function closeTopMenu() {
				 $('#gnb-wrap').css("height", "34px");
				 $('#gnb ul ul').css("height", "0px");             
             }
             
             headerInit();
